#include <cstdint>

struct Parts
{
    std::uint64_t offset, level1, level2, level3, level4;
    bool canonical;
};

Parts split(std::uint64_t address)
{
    const std::uint64_t top{ address >> 47 };                  // bits 47 to 63: 17 bits
    const bool canonical{ top == 0 || top == 0x1FFFF };       // all zeros or all ones
    return Parts{
        address & 0xFFF,
        (address >> 12) & 0x1FF,
        (address >> 21) & 0x1FF,
        (address >> 30) & 0x1FF,
        (address >> 39) & 0x1FF,
        canonical,
    };
}

std::uint64_t pageNumber(std::uint64_t address)
{
    return address >> 12;
}

unitTests:
TEST("the example")
{
    const Parts p{ split(0x00007FF6A1234567ull) };
    CHECK_EQ(p.offset, 0x567ull);
    CHECK_EQ(p.level1, 0x34ull);
    CHECK_EQ(p.level2, 0x109ull);
    CHECK_EQ(p.level3, 0x1DAull);
    CHECK_EQ(p.level4, 0xFFull);
    CHECK(p.canonical);
}
TEST("address zero") { const Parts p{ split(0) }; CHECK_EQ(p.offset + p.level1 + p.level2 + p.level3 + p.level4, 0ull); CHECK(p.canonical); }
TEST("the last user-mode byte") { const Parts p{ split(0x00007FFFFFFFFFFFull) }; CHECK_EQ(p.offset, 0xFFFull); CHECK_EQ(p.level4, 0xFFull); CHECK(p.canonical); }
TEST("kernel addresses are canonical too") { CHECK(split(0xFFFF800000000000ull).canonical); CHECK(split(0xFFFFFFFFFFFFFFFFull).canonical); }
TEST("in the gap is not canonical") { CHECK(!split(0x0000800000000000ull).canonical); CHECK(!split(0x123456789ABCDEF0ull).canonical); CHECK(!split(0xFFFF7FFFFFFFFFFFull).canonical); }
TEST("page numbers") { CHECK_EQ(pageNumber(0x1000), 1ull); CHECK_EQ(pageNumber(0x1FFF), 1ull); CHECK_EQ(pageNumber(0x00007FF6A1234567ull), 0x7FF6A1234ull); }

